  {v:"Wat is een budget?", o:["een spaarrekening met rente bij de bank","een lening die je bij de bank afsluit","een overzicht van inkomsten en uitgaven","het prijskaartje dat aan een product hangt"], g:2, u:"Wie een budget maakt, ziet of hij geld overhoudt of tekortkomt.", t:"examen-eco"},
  {v:"Wat is het verschil tussen vaste lasten en dagelijkse uitgaven in een huishouden?", o:["dagelijkse uitgaven betaal je eens per jaar","er is geen verschil tussen die twee","vaste lasten liggen vast, uitgaven wisselen","vaste lasten zijn altijd het hoogst"], g:2, u:"Ook reserveringsuitgaven horen erbij: sparen voor een nieuwe wasmachine.", t:"examen-eco"},
  {v:"Wat is een garantie?", o:["een verzekering die je er zelf bij betaalt","een korting die je op een product krijgt","de verkoper herstelt een kapot product","een lening die de winkel je geeft"], g:2, u:"Wettelijke garantie: een product moet doen wat je er redelijkerwijs van mag verwachten.", t:"examen-eco"},
  {v:"Wat is het doel van de Consumentenbond?", o:["belasting innen voor de overheid","bedrijven adviseren over hun reclamecampagnes","opkomen voor de belangen van consumenten","producten verkopen aan consumenten"], g:2, u:"Consumentenorganisaties vergelijken producten en helpen bij klachten.", t:"examen-eco"},
  {v:"Wat is een verzekering?", o:["een spaarrekening waar je rente over krijgt","een lening om een auto mee te kopen","premie betalen, schade vergoed krijgen","de garantie die de winkel je geeft"], g:2, u:"De zorgverzekering en de aansprakelijkheidsverzekering (WA) zijn verplicht voor bijna iedereen.", t:"examen-eco"},
  {v:"Wat is een eigen risico bij de zorgverzekering?", o:["de premie die je elke maand moet betalen","de kosten van een bezoek aan de huisarts","het bedrag dat je eerst zelf betaalt","het bedrag dat de overheid daarbij bijlegt"], g:2, u:"De huisarts valt niet onder het eigen risico; ziekenhuiszorg en medicijnen wel.", t:"examen-eco"},
  {v:"Wat is koop op afbetaling?", o:["eerst sparen tot je het hele bedrag hebt","nu krijgen, later in termijnen betalen","een product voor een tijdje huren","een product ruilen voor een ander"], g:1, u:"Consumptief krediet is duur; de rente kan oplopen tot boven de tien procent.", t:"examen-eco"},
  {v:"Wat is een sociale verzekering?", o:["een verzekering die alleen bedrijven afsluiten","een verplichte verzekering via de overheid","een verzekering die je zelf uitkiest","een verzekering voor je eigen huis"], g:1, u:"Werknemersverzekeringen (WW, WIA) betaal je via premies op het loon; volksverzekeringen (AOW) gelden voor iedereen.", t:"examen-eco"},
  {v:"Wat is een arbeidsovereenkomst?", o:["een cao die voor een hele bedrijfstak geldt","een vergunning om te mogen werken","een lidmaatschap van de vakbond","een contract tussen werkgever en werknemer"], g:3, u:"Minimaal moet erin staan: functie, loon, werktijden, duur van het contract.", t:"examen-eco"},
  {v:"Wat is het verschil tussen een vast en een flexibel contract?", o:["flexibel werk betaalt altijd beter dan vast","een vast contract is alleen voor ambtenaren","vast is onbepaald, flexibel is tijdelijk","er is geen verschil tussen die twee"], g:2, u:"Flexwerkers hebben minder zekerheid; werkgevers kiezen flex om snel te kunnen krimpen.", t:"examen-eco"},
  {v:"Wat is een zzp’er?", o:["een ambtenaar bij de gemeente","een zelfstandige zonder personeel","een werknemer met een vast contract","iemand die werkloos thuis zit"], g:1, u:"Een zzp’er regelt zelf zijn verzekeringen en pensioen en heeft geen recht op WW.", t:"examen-eco"},
  {v:"Wat is de ondernemingsraad?", o:["een groep aandeelhouders van het bedrijf","de vakbond binnen een bedrijf","gekozen werknemers die meepraten","de directie die het bedrijf leidt"], g:2, u:"Bedrijven met vijftig of meer werknemers moeten een ondernemingsraad hebben.", t:"examen-eco"},
  {v:"Wat is een staking?", o:["een verbod op werken dat de overheid oplegt","een pauze midden op de werkdag","het werk neerleggen om iets af te dwingen","ontslag op staande voet door de baas"], g:2, u:"Staken is een middel van vakbonden bij cao-onderhandelingen; een uiterste middel.", t:"examen-eco"},
  {v:"Wat is automatisering?", o:["meer mensen in dienst nemen","het verkorten van de werkweek","werk door machines laten doen","werk naar het buitenland verplaatsen"], g:2, u:"Automatisering verhoogt de arbeidsproductiviteit, maar kan banen kosten in sommige beroepen.", t:"examen-eco"},
  {v:"Wat is een multinational?", o:["een bedrijf met heel veel personeel in dienst","een bedrijf dat van de overheid is","een bedrijf dat alleen maar exporteert","een bedrijf met vestigingen in meer landen"], g:3, u:"Shell, Unilever en Philips zijn Nederlandse multinationals.", t:"examen-eco"},
  {v:"Wat is het verschil tussen een directe en een indirecte belasting?", o:["directe belasting is er alleen voor bedrijven","indirecte belasting betaal je eens per jaar","direct betaal je zelf, indirect zit erin","er is geen verschil; het is hetzelfde soort"], g:2, u:"Loonbelasting is direct, btw en accijns zijn indirect.", t:"examen-eco"},
  {v:"Wat is accijns?", o:["een subsidie die de overheid uitkeert","extra belasting op tabak, alcohol en benzine","een belasting over de winst van een bedrijf","een belasting over de waarde van je huis"], g:1, u:"De overheid gebruikt accijns om inkomsten te krijgen en ongezond of vervuilend gedrag te ontmoedigen.", t:"examen-eco"},
  {v:"Wat is een subsidie?", o:["een belasting op bepaalde soorten producten","een lening die je bij de bank afsluit","geld van de overheid om iets te stimuleren","een boete voor wie de regels overtreedt"], g:2, u:"Subsidies zijn een middel om gedrag te sturen; het tegenovergestelde van een heffing.", t:"examen-eco"},
  {v:"Wat is de staatsschuld?", o:["de schuld van alle bedrijven bij elkaar","alle schulden van de rijksoverheid samen","het tekort van dit ene jaar","de schuld van alle Nederlanders samen"], g:1, u:"Over de staatsschuld betaalt de overheid rente; te veel schuld beperkt de ruimte voor uitgaven.", t:"examen-eco"},
  {v:"Wat is een toeslag?", o:["een boete voor wie te laat betaalt","een extra belasting bovenop de gewone","een bijdrage bij een laag inkomen","een bonus die je werkgever geeft"], g:2, u:"Toeslagen zijn afhankelijk van je inkomen; verdien je meer, dan krijg je minder.", t:"examen-eco"},
  {v:"Wat is de betalingsbalans?", o:["de balans van een groot Nederlands bedrijf","de begroting van de rijksoverheid","alle geldstromen met het buitenland","de rekening die de bank je stuurt"], g:2, u:"Een overschot op de handelsbalans betekent: meer export dan import.", t:"examen-eco"},
  {v:"Wat is vrijhandel?", o:["handel waarbij helemaal geen geld gebruikt wordt","handel binnen de grenzen van één land","handel tussen landen zonder belemmeringen","producten die je gratis mee mag nemen"], g:2, u:"De Europese interne markt is een vorm van vrijhandel; de Wereldhandelsorganisatie (WTO) probeert het wereldwijd te bevorderen.", t:"examen-eco"},
  {v:"Wat is fairtrade?", o:["handel met alleen Europese landen","handel waarbij alles heel goedkoop is","boeren krijgen een eerlijke prijs","handel waarover geen belasting hoeft"], g:2, u:"Het Max Havelaar-keurmerk garandeert een minimumprijs en betere arbeidsomstandigheden.", t:"examen-eco"},
  {v:"Wat is de circulaire economie?", o:["een economie die helemaal zonder geld werkt","een economie met alleen nog diensten","grondstoffen worden steeds opnieuw gebruikt","een economie die in cirkels blijft groeien"], g:2, u:"Repareren, hergebruiken en recyclen in plaats van weggooien.", t:"examen-eco"},
  {v:"Wat is een CO2-heffing?", o:["een subsidie voor wie een auto koopt","een belasting op het gebruik van zuurstof","een belasting op de uitstoot van CO2","een verbod op nieuwe fabrieken"], g:2, u:"De vervuiler betaalt: bedrijven gaan zoeken naar schonere productie als uitstoot geld kost.", t:"examen-eco"},
  /* ---- erbij, 2026: meer vragen per onderdeel en per niveau ---- */
  {v:'Waar dient een budget voor?', o:["om je inkomsten en uitgaven op een rij te zetten","om rente te krijgen over je spaargeld","om een lening bij de bank te regelen","om de prijs van een product te bepalen"], g:0, u:'Met een budget hou je bij wat er binnenkomt en wat je uitgeeft, zodat je niet in de knel komt.', t:'examen-eco'},
  {v:'Wat betekent het als iets duurzaam geproduceerd is?', o:["met oog voor mens, milieu en toekomst","het gaat lang mee en is daarom duurder","het is in Nederland zelf gemaakt","het is helemaal van plastic gemaakt"], g:0, u:'Duurzaam gaat over people, planet en profit: niet alleen de prijs telt.', t:'examen-eco'},
  {v:'Wat is een consument?', o:["iemand die goederen koopt en gebruikt","iemand die producten zelf maakt","een winkel die producten verkoopt","de overheid die belasting int"], g:0, u:'Producenten maken, consumenten kopen en gebruiken.', t:'examen-eco'},
  {v:'Wat gebeurt er meestal met de gevraagde hoeveelheid als de prijs van een product stijgt?', o:['die daalt','die stijgt','die blijft altijd gelijk','die wordt nul'], g:0, u:'Dit is de wet van de vraag: hogere prijs, minder vraag, als al het andere gelijk blijft.', t:'examen-eco'},
  {v:'Wat is het verschil tussen een merkproduct en een huismerk?', o:["een huismerk is altijd van slechtere kwaliteit","een merkproduct komt altijd uit het buitenland","een huismerk is van de winkel en goedkoper","er is geen verschil; alleen de naam wisselt"], g:2, u:'Vaak komen beide uit dezelfde fabriek; het verschil zit in verpakking, marketing en marge.', t:'examen-eco'},
  {v:'Hoe bereken je de toegevoegde waarde van een bedrijf?', o:["de omzet plus de ingekochte grondstoffen","de productiewaarde min de inkoopwaarde","de winst optellen bij de betaalde belasting","het aantal werknemers maal het uurloon"], g:1, u:'Alle toegevoegde waarde in een land bij elkaar is het bruto binnenlands product.', t:'examen-eco'},
  {v:'Waarom heffen landen soms invoerrechten?', o:["om producten in de winkel goedkoper te maken","om eigen producenten te beschermen","om zelf meer te kunnen exporteren","om de inflatie omhoog te krijgen"], g:1, u:'Invoerrechten beschermen de eigen markt, maar maken producten voor de consument duurder.', t:'examen-eco'},
  {v:'Een winkel verkoopt een jas voor 80 euro exclusief 21 procent btw. Wat betaalt de klant?', o:['96,80 euro','101,00 euro','80,21 euro','63,20 euro'], g:0, u:'80 x 1,21 = 96,80 euro. De btw is 16,80 euro.', t:'examen-eco'},
  {v:'Wat is het verschil tussen een vaste en een variabele last?', o:["vaste lasten zijn altijd hoger dan variabele","variabele lasten betaal je één keer per jaar","een vaste last is elke maand gelijk","er is geen verschil tussen die twee"], g:2, u:'Bij geldproblemen kijk je eerst naar de variabele lasten: die kun je sneller bijstellen.', t:'examen-eco'},
  {v:'Wat betekent het als de economie in een hoogconjunctuur zit?', o:["de prijzen dalen in de winkels","de werkloosheid stijgt juist snel","de productie groeit en er is veel werk","de overheid gaat altijd bezuinigen"], g:2, u:'Bij laagconjunctuur is het omgekeerd: minder productie, meer werkloosheid.', t:'examen-eco'},
  {v:'Waarom kan een bedrijf goedkoper produceren als het meer produceert?', o:["de grondstoffen worden vanzelf gratis geleverd","de vaste kosten worden over meer stuks verdeeld","de btw op het product gaat dan omlaag","de werknemers gaan vanzelf sneller werken"], g:1, u:'Dit heet schaalvoordeel; het verklaart waarom grote fabrikanten vaak lagere prijzen kunnen vragen.', t:'examen-eco'},
  {v:'Een winkelier koopt een product voor 40 euro in en verkoopt het voor 60 euro exclusief btw. Hoeveel procent is de brutowinstmarge op de inkoopprijs?', o:['50 procent','33 procent','20 procent','120 procent'], g:0, u:'Winst is 20 euro op een inkoop van 40 euro: 20 : 40 x 100 = 50 procent.', t:'examen-eco'},
  {v:'Wat is het verband tussen rente en investeren door bedrijven?', o:["een hogere rente leidt juist tot meer investeringen","lage rente maakt lenen goedkoop, dus meer investeren","er is geen verband tussen die twee dingen","rente geldt alleen voor gewone consumenten"], g:1, u:'Daarom verlaagt een centrale bank de rente om de economie te stimuleren en verhoogt zij die tegen inflatie.', t:'examen-eco'},
  {v:'Waarom kan loonstijging zowel goed als slecht zijn voor de economie?', o:["loonstijging is altijd goed voor iedereen","loonstijging heeft helemaal geen effect","meer koopkracht, maar ook hogere kosten","loon heeft alleen met belasting te maken"], g:2, u:'Dit is de loon-prijsspiraal: lonen omhoog, prijzen omhoog, opnieuw looneisen.', t:'examen-eco'},
  {v:'Wat betekent het dat arbeid in Nederland relatief duur is ten opzichte van lagelonenlanden?', o:["Nederlanders werken minder hard dan anderen","er zijn helemaal geen fabrieken meer in Nederland","bedrijven verplaatsen werk of gebruiken machines","de lonen dalen hier dan vanzelf mee"], g:2, u:'Nederland concurreert daarom vooral op kennis, techniek en hoogwaardige productie.', t:'examen-eco'}
